args.ReplacementContent:
"  for await (const line of rl) {
    if (!line) continue;
    try {
      const step = JSON.parse(line);
      const str = JSON.stringify(step);
      if (str.includes('Showing lines 1 to') || str.includes('CountdownTimer')) {
        console.log('--- FOUND MATCH ---');
        console.log('Step Index:', step.step_index);
        console.log('Type:', step.type);
        console.log('Content length:', step.content?.length || 0);
        console.log('Tool calls:', step.tool_calls ? JSON.stringify(step.tool_calls).substring(0, 100) : 'none');
        // Let's write the whole step object to see it
        fs.writeFileSync(`scratch/recovered_step_raw_${step.step_index}.json`, JSON.stringify(step, null, 2));
      }
    } catch (e) {
      // ignore
    }
  }"

args.TargetContent:
"  for await (const line of rl) {
    if (!line) continue;
    try {
      const step = JSON.parse(line);
      if (step.content && step.content.includes('Showing lines 1 to 800') && step.content.includes('HomeLandingPage')) {
        console.log('--- FOUND FULL VIEW_FILE OUTPUT ---');
        console.log('Step Index:', step.step_index);
        console.log('Type:', step.type);
        fs.writeFileSync('scratch/recovered_page_view_full.txt', step.content);
        console.log('Saved to scratch/recovered_page_view_full.txt');
      }
    } catch (e) {
      // ignore
    }
  }"
